SELECT CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END AS paid_cohort, DATE_TRUNC('MONTH', paid_at) AS paid_month, SUM(amount) AS total_amount FROM payments WHERE order_id IS NULL GROUP BY CASE WHEN YEAR(paid_at) < 2024 THEN 'before_2024' WHEN YEAR(paid_at) = 2024 THEN '2024' ELSE 'after_2024' END, DATE_TRUNC('MONTH', paid_at) ORDER BY paid_cohort DESC
